DROP TABLE IF EXISTS configuracion;

CREATE TABLE `configuracion` (
  `id_configuracion` int(200) NOT NULL AUTO_INCREMENT,
  `titulo` varchar(1000) NOT NULL,
  `servicios1` varchar(200) NOT NULL,
  `servicios2` varchar(200) NOT NULL,
  `servicios3` varchar(200) NOT NULL,
  `mision` varchar(1000) NOT NULL,
  `imagen_galeria1` varchar(200) NOT NULL,
  `imagen_galeria2` varchar(200) NOT NULL,
  `vision` varchar(1000) NOT NULL,
  `direccion` varchar(200) NOT NULL,
  `google_maps` varchar(5000) NOT NULL,
  `facebook` varchar(200) NOT NULL,
  `twitter` varchar(200) NOT NULL,
  PRIMARY KEY (`id_configuracion`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

INSERT INTO configuracion VALUES("1","VETERINARIA PANDY","Atención en medicina veterinaria, tratamientos, ecografía, rehabilitación, cirugías, esterilización, limpieza dental. Vacunas, desparasitación, etc.","Estética canina, cortes,  baños, baños anti pulgas, cortes de uña, limpieza de glándulas perianales","También ofrecemos asesoramiento y  tramites de viajes, interior y exterior Venta de accesorios, alimentos y  artículos varios.","Brindar un excelente servicio veterinario, utilizando todos nuestros recursos, profesionales proporcionando un alto nivel de atención, amando lo que hacemos y por quienes lo hacemos.","vete.jpg","pet1.jpeg","Lograr nuestro mayor esfuerzo en servicios médicos veterinarios y estéticos y lograr el bienestar animal y familiar a través del compromiso ético, profesional y moral.","Irpavi, esquina calle 3, Av. Braulio Vera","https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d2509.627704702694!2d-68.08518252087595!3d-16.527441408692965!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x915f2147bc27d93d%3A0x3edb2fbd873f1174!2sVeterinaria%20Pandy!5e0!3m2!1ses!2sbo!4v1642542361191!5m2!1ses!2sbo","https://www.facebook.com/Veterinaria-Peluqueria-Canina-Pandy-110667579602377","https://www.facebook.com/Veterinaria-Peluqueria-Canina-Pandy-110667579602377");



DROP TABLE IF EXISTS detalles_pedido;

CREATE TABLE `detalles_pedido` (
  `id_detalles` int(200) NOT NULL AUTO_INCREMENT,
  `id_pedido` varchar(200) NOT NULL,
  `id_producto` int(200) NOT NULL,
  `cantidad` varchar(200) NOT NULL,
  `id_cliente` int(200) NOT NULL,
  `fecha` date NOT NULL,
  PRIMARY KEY (`id_detalles`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

INSERT INTO detalles_pedido VALUES("1","7","11","1","0","2023-10-19");



DROP TABLE IF EXISTS detalles_ventas_servicios;

CREATE TABLE `detalles_ventas_servicios` (
  `id_detalles` int(200) NOT NULL AUTO_INCREMENT,
  `id_pedido` varchar(200) NOT NULL,
  `descripcion` varchar(200) NOT NULL,
  `monto` float NOT NULL,
  PRIMARY KEY (`id_detalles`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;




DROP TABLE IF EXISTS empresa;

CREATE TABLE `empresa` (
  `id_empresa` int(100) NOT NULL AUTO_INCREMENT,
  `empresa` varchar(200) NOT NULL,
  `ruc` varchar(100) NOT NULL,
  `direccion` varchar(200) NOT NULL,
  `telefono` varchar(100) NOT NULL,
  `descripcion` varchar(2000) NOT NULL,
  `imagen` varchar(2000) NOT NULL,
  `correo` varchar(200) NOT NULL,
